# Scores whether the final claims answer has the five required parts, in Dutch.
# Return True when all parts are present. Standard library only.
import re

PARTS = {
    "besluit": r"\bbesluit\b",
    "uitkering": r"\buitkering\b",
    "eigen risico": r"\beigen risico\b",
    "onderbouwing": r"\bonderbouwing\b|\bomdat\b|\bvanwege\b",
    "volgende stappen": r"\bvolgende stappen?\b",
}
DECISION = re.compile(r"\b(niet gedekt|gedeeltelijk gedekt|gedekt)\b", re.IGNORECASE)


def evaluate(log):
    text = (log.get("output") or "").lower()
    if not DECISION.search(text):
        return False
    return all(re.search(p, text) for p in PARTS.values())

# Output guardrail for the claims agents. Return True to pass, False to block.
# Blocks a payout above the car's value: the customer's message names a "dagwaarde" with an amount
# in EUR, and the answer's "Uitkering" amount is larger. No dagwaarde in the message, or no payout
# in the answer: pass. Amounts are written the Dutch way (EUR 18.000). Standard library only.
import re

MONEY = r"(?:EUR|€)\s?(\d{1,3}(?:[.,\s]\d{3})*|\d+)"
VALUE = re.compile(r"\bdagwaarde\b\D{0,20}?" + MONEY, re.IGNORECASE)
PAYOUT = re.compile(r"\buitkering\b\D{0,30}?" + MONEY, re.IGNORECASE)


def euros(text):
    return int(re.sub(r"\D", "", text))


def evaluate(log):
    value = VALUE.search(log.get("input") or "")
    payouts = [euros(m) for m in PAYOUT.findall(log.get("output") or "")]
    if not value or not payouts:
        return True
    return max(payouts) <= euros(value.group(1))
